DROP POLICY IF EXISTS "Users manage their own entries" ON public.entries; DROP POLICY IF EXISTS "Entries are viewable by everyone" ON public.entries; DROP POLICY IF EXISTS "Users insert their own entries" ON public.entries; DROP POLICY IF EXISTS "Users update their own entries" ON public.entries; DROP POLICY IF EXISTS "Users delete their own entries" ON public.entries; CREATE POLICY "Entries are viewable by everyone" ON public.entries FOR SELECT TO authenticated USING (true); CREATE POLICY "Users insert their own entries" ON public.entries FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users update their own entries" ON public.entries FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users delete their own entries" ON public.entries FOR DELETE TO authenticated USING (auth.uid() = user_id); DROP POLICY IF EXISTS "Users manage their own profile" ON public.profiles; DROP POLICY IF EXISTS "Profiles are viewable by everyone" ON public.profiles; CREATE POLICY "Profiles are viewable by everyone" ON public.profiles FOR SELECT TO authenticated USING (true); CREATE POLICY "Users manage their own profile" ON public.profiles FOR ALL TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
